import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = "Marek Zajac"
__copyright__ = "Copyright (C) 2021, Nokia"
__email__ = "marek.Zajac@gmail.com"


class StatsMbms(GenericRtg):
    """Stats command class."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Mbms Stats command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(StatsMbms, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.sector_id = 0
        self.mbms_area = 0

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "stats mbms"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._start_stats_mbms_reset(line)
                self._start_stats_mbms(line)
            except ParsingDone:
                pass
        return super(StatsMbms, self).on_new_line(line, is_full_line)

    def _start_stats_mbms(self, line):
        """
        Start parsing methods.

        :param line: Line from device.
        :return: None.
        """
        self._parse_mbms_empty(line)
        self._parse_mbms_sector(line)
        self._parse_mbms_area(line)
        self._parse_mbms_sessions(line)

    def _start_stats_mbms_reset(self, line):
        """
        Start parsing methods if parameter options = 'reset'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "reset":
            self._parse_mbms_reset(line)

    def _parse_mbms_reset(self, line):
        """
        Check if stats were reset.

        :param line: Line from device.
        :return: None.
        """
        if "Clearing MBMS stats" in line:
            self.current_ret = {}
            self.current_ret["STATUS"] = "OK"
            raise ParsingDone

    def _parse_mbms_empty(self, line):
        """
        Check if stats data is empty.

        :param line: Line from device.
        :return: None.
        """
        if "EMPTY MBMS data" in line:
            self.current_ret = {}
            self.current_ret["STATUS"] = "EMPTY"
            raise ParsingDone

    _re_stats_sector = re.compile(r"sector-(?P<SECTOR_ID>\d+)\s+\(total:\s(?P<TOTAL>\d+(?:\.\d+)?)(?P<UNIT>B|K|M|G)\)")

    def _parse_mbms_sector(self, line):
        """
        For parsing individual sector's data.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(StatsMbms._re_stats_sector, line):
            self.sector_id = int(self._regex_helper.group("SECTOR_ID"))
            if not self.current_ret:
                self.current_ret = {}
            self.current_ret["STATUS"] = "OK"
            self.current_ret[self.sector_id] = {}
            self.current_ret[self.sector_id]["TOTAL"] = self._get_total("TOTAL", "UNIT")
            raise ParsingDone

    _re_stats_mbms_area = re.compile(
        r"^\s+PLMN:\s(?P<MCC>\d+)-(?P<MNC>\d+)\s+\/\s+MBMS-AREA:\s+(?P<MBMS_AREA>\d+)\s+\(total:\s(?P<TOTAL>\d+(?:\.\d+)?)(?P<UNIT>B|K|M|G)\)$"
    )

    def _parse_mbms_area(self, line):
        """
        For parsing individual mbms area data.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(StatsMbms._re_stats_mbms_area, line):
            self.mbms_area = int(self._regex_helper.group("MBMS_AREA"))
            self.current_ret[self.sector_id][self.mbms_area] = {}
            self.current_ret[self.sector_id][self.mbms_area]["TOTAL"] = self._get_total("TOTAL", "UNIT")
            self.current_ret[self.sector_id][self.mbms_area]["PLMN"] = (int(self._regex_helper.group("MCC")), int(self._regex_helper.group("MNC")))
            raise ParsingDone

    _re_stats_sessions = re.compile(
        r"^(\s+(?P<SAI1>\d+):\s+(?P<TOTAL1>\d+(?:\.\d+)?)(?P<UNIT1>B|K|M|G))?"
        r"(\s+(?P<SAI2>\d+):\s+(?P<TOTAL2>\d+(?:\.\d+)?)(?P<UNIT2>B|K|M|G))?"
        r"(\s+(?P<SAI3>\d+):\s+(?P<TOTAL3>\d+(?:\.\d+)?)(?P<UNIT3>B|K|M|G))?"
        r"(\s+(?P<SAI4>\d+):\s+(?P<TOTAL4>\d+(?:\.\d+)?)(?P<UNIT4>B|K|M|G))?$"
    )

    def _parse_mbms_sessions(self, line):
        """
        For parsing individual session's data.

        :param line: Line from device.
        :return:  Nothing but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(StatsMbms._re_stats_sessions, line):
            if self._regex_helper.group("SAI1"):
                sai = int(self._regex_helper.group("SAI1"))
                self.current_ret[self.sector_id][self.mbms_area][sai] = {}
                self.current_ret[self.sector_id][self.mbms_area][sai]["TOTAL"] = self._get_total("TOTAL1", "UNIT1")
            if self._regex_helper.group("SAI2"):
                sai = int(self._regex_helper.group("SAI2"))
                self.current_ret[self.sector_id][self.mbms_area][sai] = {}
                self.current_ret[self.sector_id][self.mbms_area][sai]["TOTAL"] = self._get_total("TOTAL2", "UNIT2")
            if self._regex_helper.group("SAI3"):
                sai = int(self._regex_helper.group("SAI3"))
                self.current_ret[self.sector_id][self.mbms_area][sai] = {}
                self.current_ret[self.sector_id][self.mbms_area][sai]["TOTAL"] = self._get_total("TOTAL3", "UNIT3")
            if self._regex_helper.group("SAI4"):
                sai = int(self._regex_helper.group("SAI4"))
                self.current_ret[self.sector_id][self.mbms_area][sai] = {}
                self.current_ret[self.sector_id][self.mbms_area][sai]["TOTAL"] = self._get_total("TOTAL4", "UNIT4")
            raise ParsingDone

    def _get_total(self, data, unit):
        if self._regex_helper.group(unit) == "K":
            return float(self._regex_helper.group(data)) * 1000
        if self._regex_helper.group(unit) == "M":
            return float(self._regex_helper.group(data)) * 1000000
        if self._regex_helper.group(unit) == "G":
            return float(self._regex_helper.group(data)) * 1000000000
        else:
            return float(self._regex_helper.group(data))


